//! Temporal upscaling (`--render-scale S`, 0 < S < 1): the renderer traces, denoises and
//! keeps its G-buffer at render resolution; this stage turns each frame into an
//! output-resolution image. Two modes:
//! - TAAU (upscale.wgsl): the non-learned baseline.
//! - The joint denoise + upscale network (`--joint-model FILE.wgsl`, generated by
//!   training/upscale/export.py): raw 1-spp input, this frame's guides at output
//!   resolution (raytracer.wgsl csOutputGuides, a buffer this stage owns), its own
//!   history; works at any render scale, 1 included.
#![allow(clippy::cast_possible_truncation)]
use super::gpu_buffer::UniformBuffer;
use wgpu::util::DeviceExt;

#[repr(C)]
#[derive(Clone, Copy, bytemuck::Pod, bytemuck::Zeroable)]
struct Params {
    // The joint network reads the first 32 bytes (JnParams).
    render_size: [u32; 2],
    output_size: [u32; 2],
    jitter: [f32; 2],
    history_valid: u32,
    clamp_history: u32,
    alpha_min: f32,
    alpha_max: f32,
    pad: [u32; 2],
}

/// The render scale from `--render-scale` (1 = no upscaling).
pub fn render_scale() -> f32 {
    crate::argument_value("--render-scale").map_or(1., |v| {
        let s: f32 = v.parse().expect("--render-scale must be a number");
        assert!(s > 0. && s <= 1., "--render-scale must be in (0, 1]");
        s
    })
}

/// Render resolution for an output resolution.
pub fn render_size(output: (u32, u32)) -> (u32, u32) {
    let s = render_scale();
    (
        ((output.0 as f32 * s).round() as u32).max(1),
        ((output.1 as f32 * s).round() as u32).max(1),
    )
}

/// `--joint-model FILE.wgsl`: the joint network's WGSL and weights (FILE.bin).
pub struct JointModel {
    pub source: String,
    pub weights: Vec<u8>,
}

impl JointModel {
    /// `--joint-model FILE.wgsl`, or its f16 variant FILE.f16.wgsl (export.py --f16:
    /// the convs in f16 math) when the device has SHADER_F16 and the file exists
    /// (RT_JN_F32 keeps f32).
    pub fn from_args(device: &wgpu::Device) -> Option<Self> {
        let mut path = std::path::PathBuf::from(crate::argument_value("--joint-model")?);
        let half = path.with_extension("f16.wgsl");
        if device.features().contains(wgpu::Features::SHADER_F16)
            && std::env::var_os("RT_JN_F32").is_none()
            && half.exists()
        {
            path = half;
        }
        let source = std::fs::read_to_string(&path)
            .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
        let bin = path.with_extension("bin");
        let weights =
            std::fs::read(&bin).unwrap_or_else(|e| panic!("cannot read {}: {e}", bin.display()));
        Some(Self { source, weights })
    }

    /// Entry points in dispatch order, and whether each runs on the half-resolution grid.
    fn kernels(&self) -> Vec<(String, bool)> {
        self.source
            .split("fn ")
            .skip(1)
            .filter_map(|rest| rest.split('(').next())
            .filter(|name| name.starts_with("csJn"))
            .map(|name| {
                let half = name == "csJnPool" || name.starts_with("csJnConv");
                (name.to_owned(), half)
            })
            .collect()
    }

    fn constant(&self, name: &str) -> u64 {
        self.optional_constant(name)
            .unwrap_or_else(|| panic!("joint model without {name}"))
    }

    fn optional_constant(&self, name: &str) -> Option<u64> {
        self.source
            .split(&format!("const {name} = "))
            .nth(1)
            .and_then(|rest| rest.split('u').next())
            .and_then(|n| n.trim().parse().ok())
    }

    /// The f32 weight rows, and an f16 variant's f16 rows (after JN_W32 f32 rows).
    fn weight_parts(&self) -> (&[u8], Option<&[u8]>) {
        match self.optional_constant("JN_W32") {
            Some(rows) => {
                let (f32_rows, f16_rows) = self.weights.split_at(rows as usize * 16);
                (f32_rows, Some(f16_rows))
            }
            None => (&self.weights, None),
        }
    }
}

/// Whether `--joint-model` is given (it implies ReSTIR, the G-buffer and raw input).
pub fn joint_requested() -> bool {
    crate::argument_value("--joint-model").is_some()
}

/// `--detail-upscale`: the detail upscaler (detail.wgsl) instead of TAAU.
pub fn detail_requested() -> bool {
    crate::has_flag("--detail-upscale") && !joint_requested()
}

/// Whether the upscaler needs this frame's guides at output resolution.
pub fn output_guides_requested() -> bool {
    joint_requested() || detail_requested()
}

struct Joint {
    /// f16 variant: the f16 weight rows (binding 13).
    weights16: Option<wgpu::Buffer>,
    /// Kernel, whether it runs on the half-resolution grid, its name (profiler label).
    pipelines: Vec<(wgpu::ComputePipeline, bool, &'static str)>,
    weights: wgpu::Buffer,
    feature_groups: u64,
    hidden_groups: u64,
}

pub struct Upscaler {
    pipeline: Option<wgpu::ComputePipeline>,
    joint: Option<Joint>,
    /// `--detail-upscale` (detail.wgsl): csDetailCurrent, csDetailResolve.
    detail: Option<[wgpu::ComputePipeline; 2]>,
    layout: wgpu::BindGroupLayout,
    params: wgpu::Buffer,
    /// Ping-pong history and the two bind groups reading one, writing the other.
    groups: [wgpu::BindGroup; 2],
    output: wgpu::Buffer,
    /// Joint mode: this frame's guides at output resolution (csOutputGuides writes them).
    out_guides: Option<wgpu::Buffer>,
    /// Display bindings for the output image (output-sized frame data).
    pub display: wgpu::BindGroup,
    display_frame: UniformBuffer,
    output_size: (u32, u32),
    render_size: (u32, u32),
    parity: usize,
    history_valid: bool,
    /// Denoised input: clamp history to the neighbourhood and blend faster (TAAU).
    denoised: bool,
}

impl Upscaler {
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        device: &wgpu::Device,
        image: &wgpu::Buffer,
        gbuffer: &wgpu::Buffer,
        display_layout: &wgpu::BindGroupLayout,
        exposure: &wgpu::Buffer,
        output_size: (u32, u32),
        render_size: (u32, u32),
        denoised: bool,
        joint_model: Option<&JointModel>,
        detail: bool,
    ) -> Self {
        let storage = |binding, read_only| wgpu::BindGroupLayoutEntry {
            binding,
            visibility: wgpu::ShaderStages::COMPUTE,
            ty: wgpu::BindingType::Buffer {
                ty: wgpu::BufferBindingType::Storage { read_only },
                has_dynamic_offset: false,
                min_binding_size: None,
            },
            count: None,
        };
        let uniform = wgpu::BindGroupLayoutEntry {
            binding: 0,
            visibility: wgpu::ShaderStages::COMPUTE,
            ty: wgpu::BindingType::Buffer {
                ty: wgpu::BufferBindingType::Uniform,
                has_dynamic_offset: false,
                min_binding_size: None,
            },
            count: None,
        };
        let entries: Vec<_> = if let Some(model) = joint_model {
            [uniform]
                .into_iter()
                .chain([1, 2, 3, 4].map(|b| storage(b, true)))
                .chain((5..12).map(|b| storage(b, false)))
                .chain([storage(12, true)])
                .chain(model.weight_parts().1.map(|_| storage(13, true)))
                .collect()
        } else if detail {
            [uniform]
                .into_iter()
                .chain([1, 2, 3, 4].map(|b| storage(b, true)))
                .chain([5, 6, 7].map(|b| storage(b, false)))
                .collect()
        } else {
            vec![
                uniform,
                storage(1, true),
                storage(2, true),
                storage(3, true),
                storage(4, false),
                storage(5, false),
            ]
        };
        let layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("upscaler layout"),
            entries: &entries,
        });
        let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("upscaler"),
            bind_group_layouts: &[Some(&layout)],
            immediate_size: 0,
        });
        let compute = |module: &wgpu::ShaderModule, entry: &str| {
            device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
                label: Some(entry),
                layout: Some(&pipeline_layout),
                module,
                entry_point: Some(entry),
                compilation_options: Default::default(),
                cache: None,
            })
        };
        let (pipeline, joint) = if let Some(model) = joint_model {
            let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
                label: Some("joint denoise + upscale network"),
                source: wgpu::ShaderSource::Wgsl(model.source.as_str().into()),
            });
            let joint = Joint {
                pipelines: model
                    .kernels()
                    .iter()
                    .map(|(name, half)| {
                        let label: &'static str = Box::leak(name.clone().into_boxed_str());
                        (compute(&module, name), *half, label)
                    })
                    .collect(),
                weights: device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
                    label: Some("joint network weights"),
                    contents: model.weight_parts().0,
                    usage: wgpu::BufferUsages::STORAGE,
                }),
                weights16: model.weight_parts().1.map(|rows| {
                    device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
                        label: Some("joint network f16 weights"),
                        contents: rows,
                        usage: wgpu::BufferUsages::STORAGE,
                    })
                }),
                feature_groups: model.constant("JN_FEATURE_GROUPS"),
                hidden_groups: model.constant("JN_HIDDEN_GROUPS"),
            };
            (None, Some(joint))
        } else if detail {
            (None, None)
        } else {
            let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
                label: Some("upscaler"),
                source: wgpu::ShaderSource::Wgsl(include_str!("upscale.wgsl").into()),
            });
            (Some(compute(&module, "csUpscale")), None)
        };
        let detail = (joint.is_none() && detail).then(|| {
            let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
                label: Some("detail upscaler"),
                source: wgpu::ShaderSource::Wgsl(include_str!("detail.wgsl").into()),
            });
            [
                compute(&module, "csDetailCurrent"),
                compute(&module, "csDetailResolve"),
            ]
        });
        let params = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("upscaler parameters"),
            size: std::mem::size_of::<Params>() as u64,
            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        });
        let display_frame = UniformBuffer::new(device, 16, 0, Some("upscaled frame data"));
        let (groups, output, out_guides, display) = Self::bind(
            device,
            &layout,
            &params,
            joint.as_ref(),
            detail.is_some(),
            image,
            gbuffer,
            display_layout,
            &display_frame,
            exposure,
            output_size,
        );
        Self {
            pipeline,
            joint,
            detail,
            layout,
            params,
            groups,
            output,
            out_guides,
            display,
            display_frame,
            output_size,
            render_size,
            parity: 0,
            history_valid: false,
            denoised,
        }
    }

    #[allow(clippy::too_many_arguments, clippy::type_complexity)]
    fn bind(
        device: &wgpu::Device,
        layout: &wgpu::BindGroupLayout,
        params: &wgpu::Buffer,
        joint: Option<&Joint>,
        detail: bool,
        image: &wgpu::Buffer,
        gbuffer: &wgpu::Buffer,
        display_layout: &wgpu::BindGroupLayout,
        display_frame: &UniformBuffer,
        exposure: &wgpu::Buffer,
        (width, height): (u32, u32),
    ) -> (
        [wgpu::BindGroup; 2],
        wgpu::Buffer,
        Option<wgpu::Buffer>,
        wgpu::BindGroup,
    ) {
        let pixels = (u64::from(width) * u64::from(height)).max(1);
        let half = (u64::from(width.div_ceil(2)) * u64::from(height.div_ceil(2))).max(1);
        let buffer = |label, size: u64| {
            device.create_buffer(&wgpu::BufferDescriptor {
                label: Some(label),
                size,
                usage: wgpu::BufferUsages::STORAGE,
                mapped_at_creation: false,
            })
        };
        // History: TAAU rgb + depth; joint rgb + distance, normal + kind as packed f16.
        let history_bytes = 16;
        let history: [wgpu::Buffer; 2] =
            std::array::from_fn(|_| buffer("upscaler history", history_bytes * pixels));
        let output = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("upscaled image"),
            contents: &vec![0u8; 12 * pixels as usize],
            usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
        });
        fn entry(binding: u32, buffer: &wgpu::Buffer) -> wgpu::BindGroupEntry<'_> {
            wgpu::BindGroupEntry {
                binding,
                resource: buffer.as_entire_binding(),
            }
        }
        let (groups, out_guides) = if let Some(joint) = joint {
            let out_guides = device.create_buffer(&wgpu::BufferDescriptor {
                label: Some("output-resolution guides"),
                size: 48 * pixels,
                usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_DST,
                mapped_at_creation: false,
            });
            // Packed f16 vec4s: 8 bytes each.
            let features = buffer("joint features", 8 * joint.feature_groups * pixels);
            let hidden: [wgpu::Buffer; 2] = std::array::from_fn(|_| {
                buffer("joint hidden layer", 8 * joint.hidden_groups * half)
            });
            let filter = buffer("joint filter ping-pong", 16 * pixels);
            let warp = buffer("joint warp record", 16 * pixels);
            let groups = std::array::from_fn(|parity| {
                let mut entries = vec![
                    entry(0, params),
                    entry(1, image),
                    entry(2, gbuffer),
                    entry(3, &out_guides),
                    entry(4, &history[parity]),
                    entry(5, &history[1 - parity]),
                    entry(6, &output),
                    entry(7, &features),
                    entry(8, &hidden[0]),
                    entry(9, &hidden[1]),
                    entry(10, &filter),
                    entry(11, &warp),
                    entry(12, &joint.weights),
                ];
                entries.extend(joint.weights16.as_ref().map(|w| entry(13, w)));
                device.create_bind_group(&wgpu::BindGroupDescriptor {
                    label: Some("joint network bindings"),
                    layout,
                    entries: &entries,
                })
            });
            (groups, Some(out_guides))
        } else if detail {
            let out_guides = device.create_buffer(&wgpu::BufferDescriptor {
                label: Some("output-resolution guides"),
                size: 48 * pixels,
                usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_DST,
                mapped_at_creation: false,
            });
            let current = buffer("detail current colour", 8 * pixels);
            let groups = std::array::from_fn(|parity| {
                device.create_bind_group(&wgpu::BindGroupDescriptor {
                    label: Some("detail upscaler bindings"),
                    layout,
                    entries: &[
                        entry(0, params),
                        entry(1, image),
                        entry(2, gbuffer),
                        entry(3, &out_guides),
                        entry(4, &history[parity]),
                        entry(5, &history[1 - parity]),
                        entry(6, &output),
                        entry(7, &current),
                    ],
                })
            });
            (groups, Some(out_guides))
        } else {
            let groups = std::array::from_fn(|parity| {
                device.create_bind_group(&wgpu::BindGroupDescriptor {
                    label: Some("upscaler bindings"),
                    layout,
                    entries: &[
                        entry(0, params),
                        entry(1, image),
                        entry(2, gbuffer),
                        entry(3, &history[parity]),
                        entry(4, &history[1 - parity]),
                        entry(5, &output),
                    ],
                })
            });
            (groups, None)
        };
        let display = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("upscaled display bindings"),
            layout: display_layout,
            entries: &[
                display_frame.binding(),
                entry(4, &output),
                entry(6, exposure),
            ],
        });
        (groups, output, out_guides, display)
    }

    /// Rebind after the render or output size (or the input buffers) changed; history restarts.
    #[allow(clippy::too_many_arguments)]
    pub fn resize(
        &mut self,
        device: &wgpu::Device,
        image: &wgpu::Buffer,
        gbuffer: &wgpu::Buffer,
        display_layout: &wgpu::BindGroupLayout,
        exposure: &wgpu::Buffer,
        output_size: (u32, u32),
        render_size: (u32, u32),
    ) {
        (self.groups, self.output, self.out_guides, self.display) = Self::bind(
            device,
            &self.layout,
            &self.params,
            self.joint.as_ref(),
            self.detail.is_some(),
            image,
            gbuffer,
            display_layout,
            &self.display_frame,
            exposure,
            output_size,
        );
        self.output_size = output_size;
        self.render_size = render_size;
        self.history_valid = false;
    }

    /// Joint mode: the buffer csOutputGuides fills with this frame's output-resolution
    /// guides (3 vec4 per pixel, the G-buffer layout) before `record`.
    pub fn out_guides(&self) -> Option<&wgpu::Buffer> {
        self.out_guides.as_ref()
    }

    pub fn output_size(&self) -> (u32, u32) {
        self.output_size
    }

    /// Upscale this frame; `jitter` is the frame's shared sub-pixel jitter, `exposure_bits`
    /// the display exposure (frame data .w).
    pub fn record(
        &mut self,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        jitter: [f32; 2],
        frame: u32,
        exposure_bits: u32,
        mut profiler: Option<&mut super::profiler::PassProfiler>,
    ) {
        let env = |name: &str, default: f32| {
            std::env::var(name).map_or(default, |v| v.parse().expect(name))
        };
        // Detail mode: the blend floor and the variance-clipping width (in the
        // alpha_max slot); RT_DETAIL_ALPHA / RT_DETAIL_GAMMA for experiments.
        let (alpha_min, alpha_max) = if self.detail.is_some() {
            (env("RT_DETAIL_ALPHA", 0.08), env("RT_DETAIL_GAMMA", 1.25))
        } else if self.denoised {
            (0.1, 0.4)
        } else {
            (0.04, 0.15)
        };
        let params = Params {
            render_size: [self.render_size.0, self.render_size.1],
            output_size: [self.output_size.0, self.output_size.1],
            jitter,
            history_valid: u32::from(self.history_valid),
            clamp_history: u32::from(self.denoised),
            alpha_min,
            alpha_max,
            pad: [0; 2],
        };
        queue.write_buffer(&self.params, 0, bytemuck::bytes_of(&params));
        queue.write_buffer(
            self.display_frame.handle(),
            0,
            bytemuck::cast_slice(&[self.output_size.0, self.output_size.1, frame, exposure_bits]),
        );
        let full = (
            self.output_size.0.div_ceil(8),
            self.output_size.1.div_ceil(8),
        );
        let half = (
            self.output_size.0.div_ceil(2).div_ceil(8),
            self.output_size.1.div_ceil(2).div_ceil(8),
        );
        let group = &self.groups[self.parity];
        if let Some(joint) = &self.joint {
            // One pass for all kernels, or (RT_PASS_TIMES) one timed pass per kernel.
            let mut kernels = joint.pipelines.iter().peekable();
            while kernels.peek().is_some() {
                let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
                    label: Some("joint network pass"),
                    timestamp_writes: None,
                });
                pass.set_bind_group(0, group, &[]);
                let mut last = "";
                for (pipeline, on_half, label) in kernels.by_ref() {
                    let groups = if *on_half { half } else { full };
                    pass.set_pipeline(pipeline);
                    pass.dispatch_workgroups(groups.0, groups.1, 1);
                    last = label;
                    if profiler.is_some() {
                        break;
                    }
                }
                drop(pass);
                if let Some(profiler) = profiler.as_deref_mut() {
                    profiler.mark(encoder, last);
                }
            }
        } else if let Some(pipelines) = &self.detail {
            let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
                label: Some("detail upscale pass"),
                timestamp_writes: None,
            });
            pass.set_bind_group(0, group, &[]);
            for pipeline in pipelines {
                pass.set_pipeline(pipeline);
                pass.dispatch_workgroups(full.0, full.1, 1);
            }
        } else if let Some(pipeline) = &self.pipeline {
            let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
                label: Some("upscale pass"),
                timestamp_writes: None,
            });
            pass.set_bind_group(0, group, &[]);
            pass.set_pipeline(pipeline);
            pass.dispatch_workgroups(full.0, full.1, 1);
        }
        self.parity = 1 - self.parity;
        self.history_valid = true;
    }

    /// The upscaled image, 3 floats per pixel at output resolution (for evaluation).
    #[allow(dead_code)]
    pub fn output(&self) -> &wgpu::Buffer {
        &self.output
    }
}
